{"question_id": 28, "sql": "SELECT schools.School, schools.DOC FROM frpm JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE schools.FundingType = 'Locally funded' AND (frpm.\"Enrollment (K-12)\" - frpm.\"Enrollment (Ages 5-17)\") > (SELECT AVG(f.\"Enrollment (K-12)\" - f.\"Enrollment (Ages 5-17)\") FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE s.FundingType = 'Locally funded')"}
{"question_id": 36, "sql": "SELECT schools.AdmFName1, schools.AdmLName1, schools.AdmFName2, schools.AdmLName2, schools.AdmFName3, schools.AdmLName3 FROM satscores JOIN schools ON CAST(satscores.cds AS INTEGER) = CAST(schools.CDSCode AS INTEGER) WHERE satscores.rtype = 'S' AND satscores.NumGE1500 = (SELECT MAX(NumGE1500) FROM satscores WHERE rtype = 'S')"}
{"question_id": 62, "sql": "SELECT COUNT(*) FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE schools.County = 'Los Angeles' AND schools.Charter = 0 AND (frpm.\"Free Meal Count (K-12)\" * 100.0 / frpm.\"Enrollment (K-12)\") < 0.18"}
{"question_id": 83, "sql": "SELECT schools.City, COUNT(*) FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE schools.Magnet = 1 AND schools.GSoffered = 'K-8' AND frpm.\"NSLP Provision Status\" = 'Multiple Provision Types' GROUP BY schools.City"}
{"question_id": 87, "sql": "SELECT AdmEmail1, AdmEmail2 FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31' AND SOC = '62'"}
{"question_id": 12, "sql": "SELECT MAX(frpm.\"Free Meal Count (Ages 5-17)\" * 1.0 / frpm.\"Enrollment (Ages 5-17)\") AS max_ratio FROM satscores JOIN frpm ON CAST(satscores.cds AS INTEGER) = CAST(frpm.CDSCode AS INTEGER) WHERE satscores.NumGE1500 * 1.0 / satscores.NumTstTakr > 0.3"}
{"question_id": 23, "sql": "SELECT schools.School, schools.Street FROM frpm JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE (frpm.\"Enrollment (K-12)\" - frpm.\"Enrollment (Ages 5-17)\") > 30"}
{"question_id": 24, "sql": "SELECT frpm.\"School Name\" FROM frpm JOIN satscores ON CAST(frpm.CDSCode AS INTEGER) = CAST(satscores.cds AS INTEGER) WHERE frpm.\"Free Meal Count (K-12)\" * 1.0 / frpm.\"Enrollment (K-12)\" > 0.1 AND satscores.NumGE1500 > 0"}
{"question_id": 25, "sql": "SELECT satscores.sname, frpm.\"Charter Funding Type\" FROM satscores JOIN frpm ON CAST(satscores.cds AS INTEGER) = CAST(frpm.CDSCode AS INTEGER) WHERE satscores.dname LIKE 'Riverside%' AND satscores.AvgScrMath > 400"}
{"question_id": 26, "sql": "SELECT frpm.\"School Name\", schools.Street, schools.City, schools.State, schools.Zip FROM frpm JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE frpm.\"County Name\" = 'Monterey' AND frpm.\"School Type\" = 'High Schools (Public)' AND frpm.\"FRPM Count (Ages 5-17)\" > 800"}
{"question_id": 27, "sql": "SELECT schools.School, satscores.AvgScrWrite, schools.Phone FROM schools JOIN satscores ON CAST(schools.CDSCode AS INTEGER) = CAST(satscores.cds AS INTEGER) WHERE satscores.rtype = 'S' AND (schools.OpenDate > '1991-12-31' OR schools.ClosedDate < '2000-01-01')"}
{"question_id": 31, "sql": "SELECT frpm.\"Free Meal Count (K-12)\" * 1.0 / frpm.\"Enrollment (K-12)\" AS ratio FROM frpm ORDER BY frpm.\"Enrollment (K-12)\" DESC LIMIT 2 OFFSET 9"}
{"question_id": 5, "sql": "SELECT COUNT(*) FROM satscores JOIN schools ON CAST(satscores.cds AS INTEGER) = CAST(schools.CDSCode AS INTEGER) WHERE satscores.rtype = 'S' AND satscores.AvgScrMath > 400 AND schools.Virtual = 'F'"}
{"question_id": 11, "sql": "SELECT CDSCode FROM frpm WHERE (\"Enrollment (K-12)\" + \"Enrollment (Ages 5-17)\") > 500"}
{"question_id": 17, "sql": "SELECT schools.CharterNum, satscores.AvgScrWrite, RANK() OVER (ORDER BY satscores.AvgScrWrite DESC) AS WritingScoreRank FROM schools JOIN satscores ON CAST(schools.CDSCode AS INTEGER) = CAST(satscores.cds AS INTEGER) WHERE satscores.rtype = 'S' AND satscores.AvgScrWrite > 499 AND schools.CharterNum IS NOT NULL"}
